            		self.UI.show('btn_arc_sub')
            		self.UI.show('btn_arc_add')
            		local a=3
					local me = self
local clr = self.getColorTint()
 arc_obj=spawnObject({
            			type='custom_model',
            			position=self.getPosition(),
            			rotation=self.getRotation(),
            			scale={a,1,a},
            			mass=0,
						use_gravity=false,
            			sound=false,
            			snap_to_grid=false,
            			callback_function=function(b)
							b.jointTo(me, {
								type='Fixed',
								collision=false
							})
            				b.setColorTint(clr)
            				b.setVar('parent',self)
